<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { naturalezaLabels } from '../services/conceptosPlanilla'
import { cambiarEstadoConceptoPlanillaEps, guardarConceptoPlanillaEps, listarConceptosPlanillaEps, listarOpcionesConceptosEps } from '../services/conceptosPlanillaEps'
import type { ConceptoEpsOption, ConceptoPlanillaEps, EpsOption } from '../interfaces/conceptosPlanillaEps.interface'
type EstadoFiltro='todos'|'activo'|'inactivo';type RegimenFiltro=number|'todos'|'ninguno'
const rows=ref<ConceptoPlanillaEps[]>([]),conceptos=ref<ConceptoEpsOption[]>([]),regimenes=ref<EpsOption[]>([]),criterio=ref(''),regimenFiltro=ref<RegimenFiltro>('todos'),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),conceptoId=ref<number|null>(null);const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const selected=computed(()=>conceptos.value.find(x=>x.id===conceptoId.value));const assignedIds=computed(()=>new Set(rows.value.filter(x=>x.id!==editing.value&&x.estado).map(x=>x.concepto_id)));const available=computed(()=>conceptos.value.filter(x=>!assignedIds.value.has(x.id)));const duplicate=computed(()=>conceptoId.value!==null&&assignedIds.value.has(conceptoId.value))
const filtered=computed(()=>{const q=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(x=>{const c=x.concepto;return(!q||`${c?.codigo??''} ${c?.descripcion??''}`.toLocaleLowerCase().includes(q))&&(regimenFiltro.value==='todos'||(regimenFiltro.value==='ninguno'?c?.regimen_id==null:c?.regimen_id===regimenFiltro.value))&&(estadoFiltro.value==='todos'||x.estado===(estadoFiltro.value==='activo'))})})
async function load(){loading.value=true;error.value='';try{const [items,opts]=await Promise.all([listarConceptosPlanillaEps(),listarOpcionesConceptosEps()]);rows.value=items;conceptos.value=opts.conceptos;regimenes.value=opts.regimenes}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:ConceptoPlanillaEps){editing.value=item?.id??null;conceptoId.value=item?.concepto_id??null;error.value='';modal.value=true}
async function save(){if(conceptoId.value===null)return void(error.value='Debe seleccionar un concepto de planilla.');if(duplicate.value)return void(error.value='El concepto ya está asignado a la EPS.');saving.value=true;error.value='';try{await guardarConceptoPlanillaEps(editing.value,conceptoId.value);modal.value=false;success.value=`Concepto EPS ${editing.value?'actualizado':'asignado'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:ConceptoPlanillaEps){const action=item.estado?'desactivar':'restaurar';if(!confirm(`¿Desea ${action} el concepto EPS ${item.concepto?.descripcion??item.concepto_id}?`))return;try{const r=await cambiarEstadoConceptoPlanillaEps(item.id);item.estado=r.estado;success.value=r.message??`Concepto EPS ${item.estado?'restaurado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
function clear(){criterio.value='';regimenFiltro.value='todos';estadoFiltro.value='todos'};onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Conceptos EPS</nav><header class="hero"><div class="mark">EPS</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Conceptos de planilla EPS</h1><p>Habilitación de conceptos institucionales para el procesamiento de la EPS actual.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Asignar concepto</button></header><aside class="help"><b>Alcance por EPS</b><span>Esta configuración no modifica el concepto principal; determina cuáles están disponibles para afectaciones y cálculos dentro de la EPS.</span></aside><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Código o descripción"></label><label>Régimen<select v-model="regimenFiltro"><option value="todos">Todos</option><option value="ninguno">Todos / sin régimen</option><option v-for="x in regimenes" :key="x.id" :value="x.id">{{x.descripcion}}</option></select></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activos</option><option value="inactivo">Inactivos</option></select></label><button class="soft" @click="clear">Limpiar</button></section><section class="table-card"><header><small>CONFIGURACIÓN POR EMPRESA</small><h2>Conceptos habilitados</h2></header><div v-if="loading" class="empty">Consultando conceptos EPS…</div><div v-else-if="!filtered.length" class="empty">No se encontraron conceptos asignados.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Descripción</th><th>Tipo</th><th>Naturaleza</th><th>Régimen</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td>{{x.id}}</td><td><b>{{x.concepto?.codigo??'N/A'}}</b></td><td>{{x.concepto?.descripcion??'Concepto no encontrado'}}</td><td>{{x.concepto?.tipo_concepto?.descripcion??'—'}}</td><td><span v-if="x.concepto" class="nature" :data-nature="x.concepto.naturaleza">{{naturalezaLabels[x.concepto.naturaleza]}}</span></td><td>{{x.concepto?.regimen?.descripcion??'TODOS'}}</td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button v-if="x.estado" class="edit" @click="open(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Restaurar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">EPS</div><div><small>CONFIGURACIÓN POR EMPRESA</small><h2>{{editing?'Editar':'Asignar'}} concepto EPS</h2></div><button type="button" @click="modal=false">×</button></header><label>Concepto de planilla *<select v-model="conceptoId"><option :value="null">Seleccione un concepto</option><option v-for="x in available" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}}</option></select><small>Solo se muestran conceptos activos que aún no están asignados.</small></label><p v-if="duplicate" class="conflict">El concepto ya está asignado a esta EPS.</p><aside v-if="selected" class="preview"><small>INFORMACIÓN DEL CONCEPTO</small><div><p><b>Código</b>{{selected.codigo}}</p><p><b>Tipo</b>{{selected.tipo_concepto?.descripcion??'—'}}</p><p><b>Naturaleza</b>{{naturalezaLabels[selected.naturaleza]}}</p><p><b>Régimen</b>{{selected.regimen?.descripcion??'Todos'}}</p></div></aside><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving||duplicate">{{saving?'Guardando…':editing?'Actualizar':'Asignar'}}</button></footer></form></div></div></template>
